// Avisos operativos de UNA empresa (dbo.operationalNotices): cierres, horarios especiales y
// avisos temporales que los agentes de WhatsApp/voz respetan antes que el horario normal.
// The backend takes the company from the token and stamps updatedByUserId; nothing else here.
// Generated by posgmo-factory (PRD prd_operationalNotice.json), fixed by hand.
import { API_BASE_URL } from '../utils/appEnv';

const LOG = '[operationalNoticeApi]';

export type NoticeType = 'cierre' | 'horario_especial' | 'aviso';
export type NoticeState = 'vigente' | 'programado' | 'vencido' | 'finalizado';

export interface OperationalNotice {
  operationalNoticeId: number;
  companyId: number;
  templateId: number | null;
  branchId: number | null;
  title: string;
  noticeType: NoticeType;
  customerMessage: string;
  /** Hermosillo calendar days 'YYYY-MM-DD'. */
  startDate: string;
  endDate: string;
  /** 'HH:MM' or '' (whole day). */
  startTime: string;
  endTime: string;
  blocksReservations: boolean;
  status: 'activo' | 'finalizado';
  state: NoticeState;
  updatedAt: string;
}

export interface OperationalNoticeInput {
  companyId: number;
  templateId: number | null;
  branchId: number | null;
  title: string;
  noticeType: NoticeType;
  customerMessage: string;
  startDate: string;
  endDate: string;
  startTime: string;
  endTime: string;
  blocksReservations: boolean;
}

interface Row extends Omit<OperationalNotice, 'blocksReservations' | 'updatedAt'> {
  blocksReservations: number;
  updated_at?: string;
}

async function post<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error || data?.status === 'error') {
    const message = data?.message || data?.error || data?.detail || `HTTP ${res.status}`;
    console.error(LOG, path, message);
    throw new Error(typeof message === 'string' ? message : 'Error');
  }
  return data as T;
}

const toBody = (input: Partial<OperationalNoticeInput>) => ({
  ...input,
  blocksReservations: input.blocksReservations === undefined ? undefined : (input.blocksReservations ? 1 : 0),
});

/** Current + scheduled notices; includePast adds the ones ended/finalized in the last 90 days. */
export async function getAllOperationalNotices(companyId: number, includePast = true): Promise<OperationalNotice[]> {
  const data = await post<{ operationalNotices?: Row[] }>(
    '/all_operationalNotices', { operationalNotices: [{ companyId, includePast: includePast ? 1 : 0 }] });
  const rows = (data.operationalNotices ?? []).map(({ updated_at, ...r }) => ({
    ...r,
    blocksReservations: Number(r.blocksReservations) === 1,
    updatedAt: updated_at ?? '',
  }));
  console.log(LOG, 'all', companyId, rows.length);
  return rows;
}

/** Publish (action 1). Returns the new operationalNoticeId. */
export async function publishOperationalNotice(input: OperationalNoticeInput): Promise<number> {
  const data = await post<{ value?: number }>('/operationalNotices', { operationalNotices: [{ action: 1, ...toBody(input) }] });
  return Number(data.value) || 0;
}

/** Update / extend (action 2): only the keys sent change; '' clears startTime/endTime. */
export async function updateOperationalNotice(
  companyId: number, operationalNoticeId: number, changes: Partial<Omit<OperationalNoticeInput, 'companyId'>>,
): Promise<void> {
  await post('/operationalNotices', {
    operationalNotices: [{ action: 2, companyId, operationalNoticeId, ...toBody(changes) }],
  });
}

/** Finalize early (action 3): the agents stop using it right away. */
export async function finalizeOperationalNotice(companyId: number, operationalNoticeId: number): Promise<void> {
  await post('/operationalNotices', { operationalNotices: [{ action: 3, companyId, operationalNoticeId }] });
}
